/* @author MILO-GAO(高振銘)@2020 */ package page2020.flow;import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.Map;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import page2020.View;import page2020.core.App;import page2020.core.Name.PageKey;import page2020.core.Name.Path;import page2020.core.Page;import page2020.unit.Func;import page2020.unit.Umenu;import page2020.unit.Unavbar;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Element;import page2020.view.H5;import page2020.view.bs4.B4color.Color;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.P;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3font.Weight;import page2020.view.css3.C3show;import page2020.view.css3.C3show.Overflow;import page2020.view.css3.C3show.Position;import page2020.view.html5.H5header;import page2020.view.html5.H5img;import page2020.view.html5.H5main;import secure2020.data.SecureUser;@Componentpublic class PagePersonal implements Personal {	private Umenu menu = new Umenu();	private Map<String, Unavbar> navbars = new HashMap<String, Unavbar>();	private Map<String, Umenu> menus = new HashMap<String, Umenu>();	@Autowired	private SecureUser user;	@Override	public View home(String sysCode) {		Page page = App.sysPage(sysCode);			H5img image = B4.image().round().src(page.getLogo()[2]).width(page.getZoom());		return new View().append(B4.element().pb(3).center(image));	}	@Override	public List<String> script() {		List<String> array = new ArrayList<String>();		array.add(Path.page2020 + "layout.page.js");		return array;	}	@Override	public Element<?, ?> navbar(Page page) {		String sysCode = this.user.getSysCode();		Unavbar navbar = (Unavbar) this.user.getNavbars().get(sysCode);		if (navbar == null) {			navbar = this.navbars.get(sysCode);			if (navbar == null) {				navbar = new Unavbar(sysCode).copy();				this.navbars.put(sysCode, navbar);			}			navbar.personal(this.user.getPermission());			navbar.fullname(this.user);			this.user.getNavbars().put(sysCode, navbar);		}		this.user.setNavbar(navbar);		return navbar;	}	@Override	public Element<?, ?> menu(Page page) {		String sysCode = this.user.getSysCode();		Umenu menu = (Umenu) this.user.getMenus().get(sysCode);		if (menu == null) {			menu = this.menus.get(sysCode);			if (menu == null) {				Page sysPage = App.sysPage(sysCode);				menu = this.menu.copy();				menu.color(sysPage.getBarColor(), sysPage.getBarBg(), sysPage.getBarActive());				this.menus.put(sysCode, menu.copy());			}			menu.personal(this.user.getPermission());			this.user.getMenus().put(sysCode, menu);					}		this.user.setMenu(menu);		return menu;	}	@Override	public H5header header(Page page, Func func) {		H5header header = H5.header().cssClass("px-3", "pt-2", "pb-0").css(			C3.show.position(C3show.Position.absolute),			C3.box.left("0"), C3.box.top("0"), C3.width("100%"), C3.height("auto"));		if (page.getHeaderColor() != null) {			header.css(C3.color(page.getHeaderColor()));		} else {			header.cssClass(Color.primary);		}		if (func != null && EmptyUtil.not(func.getIcon())) {			header.cssClass(TextX.nowrap)				.css(C3.font.size("1.25rem"), C3.font.weight(Weight.bold))				.append(					H5.icon(func.getIcon()),					H5.span().cssClass("ml-1").code(func.getCode())				);			if (EmptyUtil.not(func.getSubCode())) {				header.append(H5.span()					.css(C3.font.weight(Weight.normal), C3.font.size("1rem"))					.code(func.getSubCode())				);			}		}		return header;	}	public B4element buttonBox(Page page, B4element buttonBox) {		buttonBox.name(PageKey.buttons).p(2).css(			C3.show.position(C3show.Position.absolute),			C3.box.left("0"), C3.box.top("0"), C3.width("100%"), C3.height("auto"));		final String buttons = "div[data-name='" + PageKey.buttons + "'] button";		if (page.getUi() >= 1) {			page.selector(buttons,				C3.padding("0.25rem 1rem"), 				C3.margin("0.125rem 0.125rem 0 0"),				C3.border.radius("1rem")			);		}		return buttonBox;	}	public H5main main(Page page, H5main main) {		if (page.getBodyColor() != null) {			main.css(C3.color(page.getBodyColor()));		}		return main.cssClass("px-2").css(			C3.show.position(C3show.Position.absolute),			C3.box.left("0"), C3.box.top("0"), C3.width("100%"), C3.height("auto"),			C3.show.overflow(Overflow.auto)		);	}	@Override	public void layout(Page page) {		B4element content = (B4element) page.get(0);		String sysCode = this.user.getSysCode();		Unavbar navbar = (Unavbar) this.user.getNavbars().get(sysCode);		if (navbar == null) {			navbar = (Unavbar) this.navbar(page);			this.user.getNavbars().put(sysCode, (Element<?, ?>) navbar);		}		navbar.selector(page);		page.append(navbar);		Umenu menu = (Umenu) this.user.getMenus().get(sysCode);		if (menu == null) {			menu = (Umenu) this.menu(page);			this.user.getMenus().put(sysCode, (Element<?, ?>) menu);		}		menu.selector(page);		page.append(menu);		content.css(C3.show.position(Position.fixed),				C3.box.left("20%"), C3.box.top("50px"), C3.width("80%"));				navbar.cssClass(P.fixTop, "p-0").height("50px");		menu.css(C3.show.position(Position.fixed), C3.show.overflow(Overflow.auto),			C3.box.left("0"), C3.box.top("50px"), C3.width("20%"));			}}